//! Independent readback and real evaluation of closed generated byte literals.

use std::collections::BTreeMap;

use crate::support::{self, P};
use serde_json::json;

const ARRAY: &str = "_root_.ByteArray.mk #[";
const OCTET: &str = "_root_.UInt8.ofNat (nat_lit ";

struct Reader<'a> {
    remaining: &'a str,
}

impl Reader<'_> {
    fn take(&mut self, expected: &str) -> Result<(), String> {
        self.remaining = self
            .remaining
            .strip_prefix(expected)
            .ok_or_else(|| format!("expected closed byte syntax {expected:?}"))?;
        Ok(())
    }

    fn octet(&mut self) -> Result<u8, String> {
        let count = self
            .remaining
            .bytes()
            .take_while(u8::is_ascii_digit)
            .count();
        let number = &self.remaining[..count];
        let value: u8 = number.parse().map_err(|_| "an octet is exactly 0..255")?;
        if number != value.to_string() {
            return Err("an octet has canonical decimal spelling".to_owned());
        }
        self.remaining = &self.remaining[count..];
        Ok(value)
    }

    fn binding(&mut self) -> Result<(u8, u8), String> {
        self.take("let __byte")?;
        let name = self.octet()?;
        self.take(" : _root_.UInt8 := ")?;
        self.take(OCTET)?;
        let value = self.octet()?;
        self.take("); ")?;
        Ok((name, value))
    }
}

// This reader recognizes a closed grammar; it does not evaluate Lean, call the
// renderer, or infer a value from the name of an unchecked shared binding.
fn read_prefix(text: &str) -> Result<(Vec<u8>, usize), String> {
    let mut reader = Reader { remaining: text };
    let shared = text.starts_with("(let ");
    let mut bindings = BTreeMap::new();
    if shared {
        reader.take("(")?;
        while reader.remaining.starts_with("let ") {
            let (name, value) = reader.binding()?;
            if name != value
                || bindings
                    .last_key_value()
                    .is_some_and(|(prior, _)| *prior >= name)
            {
                return Err("shared octets must be exact, distinct and ascending".to_owned());
            }
            bindings.insert(name, value);
        }
        if bindings.is_empty() {
            return Err("a shared expression must bind an octet".to_owned());
        }
    }
    reader.take(ARRAY)?;
    let mut values = Vec::new();
    let mut references = BTreeMap::<u8, usize>::new();
    if !reader.remaining.starts_with(']') {
        loop {
            let value = if reader.remaining.starts_with("__byte") {
                reader.take("__byte")?;
                let name = reader.octet()?;
                let value = *bindings
                    .get(&name)
                    .ok_or("a shared reference must be bound")?;
                *references.entry(name).or_default() += 1;
                value
            } else {
                reader.take("(")?;
                reader.take(OCTET)?;
                let value = reader.octet()?;
                reader.take("))")?;
                if bindings.contains_key(&value) {
                    return Err("a shared octet cannot also be inlined".to_owned());
                }
                value
            };
            values.push(value);
            if reader.remaining.starts_with(']') {
                break;
            }
            reader.take(", ")?;
        }
    }
    reader.take("]")?;
    if shared {
        reader.take(")")?;
    }
    let mut counts = BTreeMap::<u8, usize>::new();
    for value in &values {
        *counts.entry(*value).or_default() += 1;
    }
    for (value, count) in &counts {
        if (*count >= 4) != bindings.contains_key(value) {
            return Err(
                "exactly the octets occurring at least four times must be shared".to_owned(),
            );
        }
    }
    if bindings
        .keys()
        .any(|value| references.get(value).copied().unwrap_or(0) < 4)
    {
        return Err("every binding must be used at least four times".to_owned());
    }
    Ok((values, text.len() - reader.remaining.len()))
}

fn read_expression(text: &str) -> Result<Vec<u8>, String> {
    let (values, consumed) = read_prefix(text)?;
    if consumed != text.len() {
        return Err("trailing text outside the closed byte expression".to_owned());
    }
    Ok(values)
}

fn hex(values: &[u8]) -> String {
    values.iter().map(|value| format!("{value:02x}")).collect()
}

pub(super) fn emitted_literals(mut text: &str) -> Result<Vec<String>, String> {
    let mut values = Vec::new();
    while let Some(array) = text.find("ByteArray.mk #[") {
        let root = array
            .checked_sub("_root_.".len())
            .ok_or("an array must be rooted")?;
        // Locate only an immediately adjacent closed binding sequence, not
        // an unrelated earlier generated let enclosing this literal. This
        // locates byte subexpressions in the two fixed nested-record fixtures;
        // it is not a parser or authority for arbitrary surrounding Lean.
        let start = text[..root]
            .rfind("(let __byte")
            .filter(|start| {
                let mut reader = Reader {
                    remaining: &text[start + 1..root],
                };
                while !reader.remaining.is_empty() {
                    if reader.binding().is_err() {
                        return false;
                    }
                }
                true
            })
            .unwrap_or(root);
        let (bytes, consumed) = read_prefix(&text[start..])?;
        values.push(hex(&bytes));
        text = &text[start + consumed..];
    }
    if text.contains("(let __byte") {
        return Err("a binding without its byte array".to_owned());
    }
    Ok(values)
}

fn vectors() -> Vec<Vec<u8>> {
    vec![
        vec![],
        vec![0, 255, 128, 192, 175, 237, 160, 128],
        vec![0],
        vec![0; 2],
        vec![0; 3],
        vec![0; 4],
        vec![255; 4],
        vec![0, 255, 0, 255, 0, 255, 0, 255, 128],
        (0..=255).collect(),
        (0..4).flat_map(|_| 0..=255).collect(),
    ]
}

pub(super) fn verify() {
    for language in ["1.1", "1.2"] {
        verify_language(language);
    }
}

fn verify_language(language: &str) {
    let values = vectors();
    let project = P::example();
    project.edit(
        "lexlean.toml",
        "language = \"1.0\"",
        &format!("language = \"{language}\""),
    );
    let bytes_type = json!({"kind":"bytes"});
    let literal = |bytes: &[u8]| json!({"kind":"bytes", "hex":hex(bytes)});
    let append = |left, right| {
        json!({"kind":"primitive", "operation":"append", "result":bytes_type,
        "arguments":[left, right]})
    };
    let mut declarations: Vec<_> = values
        .iter()
        .enumerate()
        .map(|(index, bytes)| {
            json!({"kind":"definition", "name":format!("literal{index}"), "parameters":[],
            "result":bytes_type, "axioms":[], "body":literal(bytes)})
        })
        .collect();
    declarations.push(json!({"kind":"definition", "name":"withBinders",
        "parameters":[{"name":"llb0", "type":bytes_type}, {"name":"llb255", "type":bytes_type},
                      {"name":"nat_lit", "type":bytes_type}], "result":bytes_type, "axioms":[],
        "body":append(json!({"kind":"var", "name":"llb0"}),
            append(literal(&[0,255,0,255,0,255,0,255]),
                append(json!({"kind":"var", "name":"nat_lit"}), json!({"kind":"var", "name":"llb255"}))))}));
    let spec = if language == "1.1" {
        "lexlean/semantic-module/1"
    } else {
        "lexlean/semantic-module/2"
    };
    let module = json!({"spec":spec, "declarations":declarations});
    project.write("src/Main.lex.tex", &format!(
        "\\begin{{lexlean}}{{Main}}\n\\useglossary{{lexlean.std.nat@{language}.0}}\n\\title{{Natural number addition}}\n\\begin{{semanticmodule}}\n\\semanticdata{{{module}}}\n\\end{{semanticmodule}}\n\\end{{lexlean}}\n"
    ));
    project.relock();
    let before = project
        .engine()
        .snapshot(lexlean::CheckRequest {
            selection: lexlean::Selection::Entrypoints,
        })
        .expect("byte fixture snapshot")
        .canonical_bytes();
    let rendered = support::rendered(&project);
    let lean = support::lean_text(&rendered, "Main");
    for (index, expected) in values.iter().enumerate() {
        let marker = format!("public def literal{index} : ByteArray := ");
        let body = lean
            .lines()
            .find_map(|line| line.split_once(&marker).map(|(_, body)| body))
            .expect("the actual generated literal definition");
        assert_eq!(
            read_expression(body).expect("closed explicit-octet lowering"),
            *expected,
            "language {language}, literal{index}: every original byte in order"
        );
    }
    let tex = &rendered
        .modules
        .iter()
        .find(|module| module.module == "Main")
        .expect("Main")
        .tex_text;
    assert!(
        !tex.contains("ofNat") && !tex.contains("\\_\\_byte"),
        "canonical document must not expose lowering-only syntax"
    );
    let definitions: Vec<_> = tex
        .lines()
        .filter_map(|line| line.strip_prefix("\\noindent Definition: \\texttt{"))
        .collect();
    assert_eq!(
        definitions.len(),
        values.len() + 1,
        "all document definitions remain"
    );
    for (shown, expected) in definitions.iter().zip(&values) {
        let numbers = expected
            .iter()
            .map(u8::to_string)
            .collect::<Vec<_>>()
            .join(", ");
        assert_eq!(
            *shown,
            format!("ByteArray.mk \\#[{numbers}]}}.\\par"),
            "canonical byte display retains the original decimal numbers"
        );
    }
    let _ = support::verify_ok_backed("SM-19", &project);
    assert_eq!(
        before,
        project
            .engine()
            .snapshot(lexlean::CheckRequest {
                selection: lexlean::Selection::Entrypoints,
            })
            .expect("verified byte fixture snapshot")
            .canonical_bytes()
    );
    if support::lean_backed("SM-19") {
        evaluate(&project, &lean, &values);
    }
}

fn evaluate(project: &P, lean: &str, values: &[Vec<u8>]) {
    use lexlean::verify::child::{ChildHome, ChildSpec, Normalizer};

    let mut probes = String::new();
    for (index, bytes) in values.iter().enumerate() {
        let expected = bytes
            .iter()
            .map(u8::to_string)
            .collect::<Vec<_>>()
            .join(", ");
        probes.push_str(&format!("#eval (LexLeanExample.Main.literal{index}.toList.map UInt8.toNat) == ([{expected}] : List Nat)\n"));
    }
    probes.push_str("#eval ((LexLeanExample.Main.withBinders (ByteArray.mk #[19]) (ByteArray.mk #[29]) (ByteArray.mk #[23])).toList.map UInt8.toNat) == ([19, 0, 255, 0, 255, 0, 255, 0, 255, 23, 29] : List Nat)\n");
    let directory = tempfile::tempdir().expect("byte evaluation directory");
    let scratch = camino::Utf8Path::from_path(directory.path()).expect("UTF-8 scratch path");
    let path = scratch.join("ByteRuntime.lean");
    std::fs::write(&path, format!("{lean}\n{probes}"))
        .expect("generated bytes and independent probes");
    let _guard = support::env_shared();
    let limits = support::limits(project);
    let toolchain = lexlean::verify::toolchain::preflight(&limits).expect("pinned Lean admission");
    let bin = toolchain.root.join("bin");
    // The generated module imports the shipped runtime (SPEC.md §17.12); its
    // objects are compiled here by the same pinned Lean so the probes run the
    // actual generated text, not a copy with the import removed.
    let compiled = scratch.join("objects");
    let sources = scratch.join("runtime");
    let search = std::env::join_paths([
        compiled.as_std_path(),
        toolchain.root.join("lib/lean").as_std_path(),
    ])
    .expect("LEAN_PATH");
    for runtime in lexlean::backend::runtime::imported_by([lean]).expect("the shipped runtime") {
        let relative = runtime.name.replace('.', "/");
        let source = sources.join(format!("{relative}.lean"));
        let object = compiled.join(format!("{relative}.olean"));
        for directory in [source.parent(), object.parent()] {
            std::fs::create_dir_all(directory.expect("parent")).expect("runtime directory");
        }
        std::fs::write(&source, &runtime.text).expect("runtime source");
        let built = std::process::Command::new(&toolchain.lean.path)
            .arg("-o")
            .arg(&object)
            .arg(format!("{relative}.lean"))
            .current_dir(&sources)
            .env("LEAN_PATH", &search)
            .output()
            .expect("pinned Lean compiles the runtime");
        assert!(
            built.status.success(),
            "{} does not compile:\n{}\n{}",
            runtime.name,
            String::from_utf8_lossy(&built.stdout),
            String::from_utf8_lossy(&built.stderr)
        );
    }
    let normalizer = Normalizer::new(scratch, &project.root, scratch, &toolchain.root);
    let output = lexlean::verify::child::run(
        &ChildSpec {
            tool: "lean",
            module: Some("ByteRuntime".to_owned()),
            program: &toolchain.lean.path,
            executable_sha256: toolchain.lean.sha256,
            argv: vec![path.to_string()],
            cwd: scratch,
            extra_env: vec![(
                "LEAN_PATH".to_owned(),
                search.to_string_lossy().into_owned(),
            )],
            home: ChildHome::Toolchain {
                toolchain_bin: &bin,
            },
        },
        &limits,
        &normalizer,
    )
    .expect("pinned Lean evaluates actual generated definitions under unchanged child limits");
    assert_eq!(output.exit_code, 0, "{}\n{}", output.stdout, output.stderr);
    assert_eq!(output.stdout, "true\n".repeat(values.len() + 1));
}

#[cfg(test)]
mod tests {
    use super::{emitted_literals, read_expression, ARRAY, OCTET};

    #[test]
    fn closed_byte_oracle_refuses_foreign_noncanonical_and_unused_syntax() {
        let empty = format!("{ARRAY}]");
        assert_eq!(read_expression(&empty).expect("empty"), Vec::<u8>::new());
        let shared = "(let __byte255 : _root_.UInt8 := _root_.UInt8.ofNat (nat_lit 255); _root_.ByteArray.mk #[__byte255, __byte255, __byte255, __byte255])";
        assert_eq!(read_expression(shared).expect("shared"), vec![255; 4]);
        assert_eq!(
            emitted_literals(&format!("(let __byte0 : Nat := 9; {empty})")).expect("outer local"),
            vec![String::new()]
        );
        assert_eq!(
            emitted_literals(&format!("(let __byte0 : Nat := 9; {shared})"))
                .expect("nested local scope"),
            vec!["ffffffff"]
        );
        assert!(emitted_literals(&shared.replace("nat_lit 255", "nat_lit 254")).is_err());
        for bad in [
            "ByteArray.mk #[255]".to_owned(),
            format!("{ARRAY}({OCTET}256))]"),
            format!("{ARRAY}({OCTET}00))]"),
            format!("{ARRAY}__byte255]"),
            format!("{empty}; IO.println 0"),
            shared.replace("nat_lit 255", "nat_lit 254"),
            shared.replace("let __byte255", "let foreign"),
            shared.replace(" := _root_.UInt8.ofNat (nat_lit 255)", " := __byte255"),
            shared.replace(", __byte255", ""),
            shared.replace("; _root_.ByteArray", "; let __byte255 : _root_.UInt8 := _root_.UInt8.ofNat (nat_lit 255); _root_.ByteArray"),
            shared.replace("; _root_.ByteArray", "; let __byte254 : _root_.UInt8 := _root_.UInt8.ofNat (nat_lit 254); _root_.ByteArray"),
            shared.replace("#[__byte255", "#[(_root_.UInt8.ofNat (nat_lit 255))"),
            format!("{ARRAY}({OCTET}0)), ({OCTET}0)), ({OCTET}0)), ({OCTET}0))]"),
        ] {
            assert!(read_expression(&bad).is_err(), "unexpectedly admitted {bad}");
        }
    }

    #[test]
    fn closed_byte_oracle_reads_values_not_the_expected_literal_or_binding_name() {
        let original = format!("{ARRAY}({OCTET}0)), ({OCTET}255)), ({OCTET}128))]");
        let expected = vec![0, 255, 128];
        assert_eq!(read_expression(&original).expect("original"), expected);
        for mutant in [
            original.replace("nat_lit 255", "nat_lit 254"),
            original
                .replace("nat_lit 0", "nat_lit 255")
                .replace("nat_lit 128", "nat_lit 0"),
            original.replace(", (_root_.UInt8.ofNat (nat_lit 128))", ""),
            original.replace("nat_lit 128", "nat_lit 255"),
        ] {
            assert_ne!(
                read_expression(&mutant).expect("well-formed mutation"),
                expected
            );
        }
    }
}
